import random, collections

def flat(m,d):
 x=random.randrange(1<<m); B=[]; piv={}
 while len(B)<d:
  v=random.randrange(1<<m); u=v
  while u:
   k=u.bit_length()-1
   if k in piv:u^=piv[k]
   else: piv[k]=u;B.append(v);break
 S=[x]
 for v in B:S += [x^v for x in S]
 return sum(1<<x for x in S)
for m,d in [(8,4),(14,7)]:
 ct=collections.Counter()
 fs=[flat(m,d) for i in range(300)]
 for i in range(100000):
  f=0
  for _ in range(random.randrange(2,9)):f^=random.choice(fs)
  w=f.bit_count()
  if w<2.5*(1<<d):ct[w]+=1
 print(m, sorted(ct.items()))

