import itertools,pickle,time
N=14;r=7
S={}
def comps(caps,total,prefix=()):
 if len(caps)==1:
  if 0<=total<=caps[0]:yield prefix+(total,)
 else:
  for i in range(max(0,total-sum(caps[1:])),min(caps[0],total)+1):
   yield from comps(caps[1:],total-i,prefix+(i,))
start=time.time();cnt=0
for ov in range(8):
 # patterns of A B support constraints
 caps=[ov,7-ov,7-ov,ov]; pat=[3,1,2,0]
 for cs in comps(caps,7):
  ns=[];ps=[]
  for n,c,p in zip(caps,cs,pat):
   ns.extend([c,n-c]);ps.extend([p|4,p])
  for ds in comps(ns,7):
   unions=[0]*16
   for n,d,p in zip(ns,ds,ps):
    for pp,nn in [(p|8,d),(p,n-d)]:
     if nn:
      for mask in range(1,16):
       if pp&mask:unions[mask]+=nn
   w=sum((-2)**(mask.bit_count()-1)*(1<<(14-unions[mask])) for mask in range(1,16))
   cnt+=1
   if w not in S:S[w]=(ov,cs,ds)
print('count,time',cnt,time.time()-start)
print('all <384',sorted(x for x in S if x<384))
print('missing 320..512', sorted(set(range(320,513,2))-S.keys()))
pickle.dump(S,open('four.pkl','wb'))

