import itertools,random,pickle,time
m=14;r=7
masks=[sum(1<<i for i in t) for t in itertools.combinations(range(m),r)]
# truth bitsets via recursion supersets
T={}
for a in masks:
 free=[i for i in range(m) if not(a>>i&1)];v=1<<a
 for i in free:v|=v<<(1<<i)
 T[a]=v
S={};random.seed(42);start=time.time()
for _ in range(1000000):
 a=random.choice(masks); f=T[a];ms=[a]
 for k in range(random.randrange(3,12)):
  a=random.choice(ms)
  for j in range(random.randrange(1,5)):
   i=random.randrange(m);j=random.randrange(m)
   if ((a>>i)^(a>>j))&1:a^=(1<<i)|(1<<j)
  ms.append(a);f^=T[a];w=f.bit_count()
  if w not in S:S[w]=ms.copy()
print('time',time.time()-start)
print('below 320',sorted(w for w in S if w<320))
print('missing320-1024', sorted(set(range(320,1025,2))-S.keys()))
pickle.dump((T,S),open('random.pkl','wb'))

