import z3,itertools,time,pickle

def parts(n,k,lo=1):
 if k==0:
  if n==0:yield ()
 else:
  for x in range(lo,min(7,n//k)+1):
   for y in parts(n-x,k-1,x):yield (x,)+y

def xor(xs):
 if not xs:return z3.BoolVal(False)
 s=xs[0]
 for x in xs[1:]:s=z3.Xor(s,x)
 return s
start=time.time();ct={}
for k in range(4,10):
 for ks in parts(14,k):
  # Need complementary degree-seven monomials for 2 mod 4 weight.
  deg=[sum(ks[i] for i in range(k) if m>>i&1) for m in range(1<<k)]
  if 7 not in deg:continue
  weights=[]
  for m in range(1<<k):
   w=1
   for i,d in enumerate(ks):
    if not(m>>i&1):w*=(1<<d)-1
   weights.append(w)
  v={m:z3.Bool('v'+str(m)) for m in range(1<<k) if weights[m]<=322}
  sol=z3.Solver();sol.set(timeout=3000)
  sol.add(z3.PbEq([(x,weights[m]) for m,x in v.items()],322))
  for m in range(1<<k):
   if deg[m]<=7:continue
   terms=[x for t,x in v.items() if t&m==t]
   if terms:sol.add(z3.Not(xor(terms)))
  ans=sol.check();ct[str(ans)]=ct.get(str(ans),0)+1
  print(ks,len(v),ans,'time',round(time.time()-start,2),flush=True)
  if ans==z3.sat:
   md=sol.model();supp=[m for m,x in v.items() if z3.is_true(md[x])]
   pickle.dump((ks,supp),open('sat322.pkl','wb'));raise SystemExit('FOUND!')
print(ct)

