import numpy as np

def kvals(n,t):
 out=[1]
 if not n:return out
 out.append(n-2*t)
 for i in range(1,n):out.append(((n-2*t)*out[-1]-(n-i+1)*out[-2])//(i+1))
 return out
profiles=[];start=time.time()
for h in range(1,4):
 for typ in [0,1,2]:
  A=[]
  for x in range(128):
   q=sum(((x>>(2*i))&1)*((x>>(2*i+1))&1) for i in range(h))%2
   if typ==1:q^=1
   if typ==2:q^=(x>>(2*h))&1
   if q:A.append(x)
  a=len(A);ss=set(A);counts=collections.Counter()
  for t in range(128):
   p=sum((x&t).bit_count()%2 for x in A)
   q=64-p if t else 0
   # all1 component as well
   counts[p,q]+=1;counts[a-p,128-a-q]+=1
  v=[]
  for (p,q),ct in counts.items():v.append((ct,kvals(a,p),kvals(128-a,q)))
  P=[]
  for i in range(1,a,2):
   for j in range(1,128-a,2):
    num=sum(ct*ki[i]*kj[j] for ct,ki,kj in v)
