 for idx2,(hh,tt,d,Q) in enumerate(profiles):
  b=np.array([t[0] for t in Q]);j=np.array([t[1] for t in Q])
  for c,i in P:
   vals=a*b+c*d-2*i*j
   loc=np.nonzero(vals==322)[0]
   if len(loc):
    k=int(loc[0]);data=(h,typ,a,c,i,hh,tt,d,int(b[k]),int(j[k]))
    print('FOUND PROFILE',data,flush=True);pickle.dump(data,open('profile322.pkl','wb'));raise SystemExit
print('none',time.time()-start)

