import z3,itertools,pickle,time

def xor(xs):
 if not xs:return z3.BoolVal(False)
 while len(xs)>1:xs=[z3.Xor(xs[i],xs[i+1]) if i+1<len(xs) else xs[i] for i in range(0,len(xs),2)]
 return xs[0]

def val(poly,x):return sum(x&a==a for a in poly)%2
Bs=[(7,), (7,25), (7,56), (67,76,112), (3,12,16)]
# B degree at most three
start=time.time()
for ku in [1,2,3]:
 A=15;C=112;D=sum(1<<i for i in list(range(ku))+list(range(4,8-ku)))
 assert D.bit_count()==4
 cost=[sum(( (s&1 and u&A==A) ^ (bool(s&2) and u&D==D) ^ (bool(s&4) and u&C==C) ) for u in range(128)) for s in range(8)]
 print('u masks',A,D,C,'costs',cost,flush=True)
 for B in Bs:
  E=[z3.Bool('E'+str(i)) for i in range(128)];F=[z3.Bool('F'+str(i)) for i in range(128)]
  sol=z3.SolverFor('QF_FD');sol.set(timeout=15000)
  weighted=[]
  for v in range(128):
   b=val(B,v)
   ys=[z3.Bool('Y'+str(v)+'_'+str(s)) for s in range(4)]
   for s,y in enumerate(ys):sol.add(y==z3.And(E[v] if s&1 else z3.Not(E[v]),F[v] if s&2 else z3.Not(F[v])))
   for s,y in enumerate(ys):weighted.append((y,cost[b+2*(s&1)+4*(s>>1)]))
  sol.add(z3.PbEq(weighted,322))
  # E cubic, F quartic via parity checks of degrees <=3 and <=2 respectively.
  for mask in range(128):
   degree=mask.bit_count()
   if degree<=3:sol.add(z3.Not(xor([E[v] for v in range(128) if v&mask==mask])))
   if degree<=2:sol.add(z3.Not(xor([F[v] for v in range(128) if v&mask==mask])))
  ans=sol.check();print('B',B,'wt',sum(val(B,x) for x in range(128)),ans,'time',round(time.time()-start,2),flush=True)
  if ans==z3.sat:
   md=sol.model();es=[int(z3.is_true(md[e])) for e in E];fs=[int(z3.is_true(md[f])) for f in F]
   pickle.dump((A,D,C,B,es,fs),open('rank3sat322.pkl','wb'));raise SystemExit('FOUND!')

