import z3,itertools,time,pickle
z3.set_param('memory_max_size',3800)
n=14;w=322;L=w-n-1
rows=[z3.BitVec('r'+str(i),L) for i in range(n)]
sol=z3.SolverFor('QF_BV');sol.set(timeout=120000)
def parity(v):
 while v.size()>1:
  k=v.size()//2
  lo=z3.Extract(k-1,0,v);hi=z3.Extract(v.size()-1,k,v)
  if lo.size()<hi.size():lo=z3.ZeroExt(1,lo)
  v=lo^hi
 return v
start=time.time()
for r in range(1,7):
 for ids in itertools.combinations(range(n),r):
  v=rows[ids[0]]
  for i in ids[1:]:v=v&rows[i]
  sol.add(parity(v)==(1 if r==1 else 0))
 print('built moment order',r,time.time()-start,flush=True)
cols=[z3.Concat(*[z3.Extract(j,j,rows[i]) for i in range(n-1,-1,-1)]) for j in range(L)]
for c in cols:sol.add(c&(c-1)!=0)
for a,b in zip(cols,cols[1:]):sol.add(z3.ULT(a,b))
for a,b in zip(rows,rows[1:]):sol.add(z3.ULT(a,b))
print('built all',time.time()-start,flush=True)
ans=sol.check();print(ans,sol.reason_unknown(),time.time()-start,flush=True)
if ans==z3.sat:
 md=sol.model();rr=[md.eval(r).as_long() for r in rows]
 S=[0]+[1<<i for i in range(n)]+[sum((rr[i]>>j&1)<<i for i in range(n)) for j in range(L)]
 assert len(S)==w and len(set(S))==w
 for r in range(7):
  for ids in itertools.combinations(range(n),r):assert sum(all(x>>i&1 for i in ids) for x in S)%2==0
 pickle.dump(S,open('original_sat322.pkl','wb'))
 print('WITNESS VERIFIED',S)

